// Per-element base and row stride inside the mask ROM.
module guide_osd_base(input [3:0] id,output reg [10:0] base,output reg [4:0] stride);
always @* begin
 base={11{1'b0}};stride=5'd15;
 case(id)
  4'd0:begin base=11'd0;stride=5'd15;end // 自动轮播中
  4'd1:begin base=11'd270;stride=5'd15;end // 手动浏览
  4'd2:begin base=11'd540;stride=5'd15;end // 讲解中
  4'd3:begin base=11'd810;stride=5'd15;end // 已暂停
  4'd4:begin base=11'd1080;stride=5'd15;end // 讲解结束
  4'd5:begin base=11'd1350;stride=5'd15;end // 待播放
  default:begin base={11{1'b0}};stride=5'd15;end
 endcase
end
endmodule
